p=/tmp; o=nosuid
set -- $(mount -p | awk -v p="$p" '$2==p {print $1, $3, $4}')
[ $# -ge 3 ] || exit 0
dev=$1; fst=$2; opts=$3
case ",$opts," in *,$o,*) exit 0;; esac
if [ "$fst" = zfs ]; then
  zfs set setuid=off "$dev"
else
  if awk -v p="$p" '$0 !~ /^#/ && $2==p {f=1} END {exit !f}' /etc/fstab 2>/dev/null; then
    tma_bk /etc/fstab
    awk -v p="$p" -v o="$o" '$0 !~ /^#/ && $2==p { n=split($4,a,","); f=0; for(i=1;i<=n;i++) if(a[i]==o) f=1; if(!f) $4=$4","o; print $1"\t"$2"\t"$3"\t"$4"\t"$5"\t"$6; next } {print}' /etc/fstab > /etc/fstab.tma.$$ &&
      [ -s /etc/fstab.tma.$$ ] && cat /etc/fstab.tma.$$ > /etc/fstab
    rm -f /etc/fstab.tma.$$
  fi
  mount -u -o "$o" "$p"
fi

