tma_sshd=$(command -v sshd 2>/dev/null || echo /usr/sbin/sshd)
tma_sshd_reload() {
  if [ -s /var/run/sshd.pid ]; then kill -HUP "$(cat /var/run/sshd.pid)" 2>/dev/null
  elif command -v svcadm >/dev/null 2>&1; then svcadm refresh svc:/network/ssh:default 2>/dev/null; fi
  return 0
}
# tma_sshd_set KEYWORD VALUE: make KEYWORD the first (effective) global setting, comment older ones,
# validate with sshd -t before replacing sshd_config.
tma_sshd_set() {
  kw=$1; val=$2; cfg=/etc/ssh/sshd_config
  [ -f "$cfg" ] || { echo "no $cfg"; return 0; }
  cur=$(awk -v kw="$kw" 'BEGIN{n=split(kw,a," ")} tolower($1)=="match"{exit} {ok=1; for(i=1;i<=n;i++) if(tolower($i)!=tolower(a[i])) ok=0; if(ok) print}' "$cfg" | awk '{$1=$1; print}')
  want=$(printf '%s %s' "$kw" "$val" | tr 'A-Z' 'a-z'); have=$(printf '%s' "$cur" | tr 'A-Z' 'a-z')
  [ "$have" = "$want" ] && return 0
  tma_bk "$cfg"; t="$cfg.tma.$$"
  { printf '%s %s\n' "$kw" "$val"
    awk -v kw="$kw" 'BEGIN{n=split(kw,a," "); m=0} { if (tolower($1)=="match") m=1; ok=!m; for(i=1;i<=n&&ok;i++) if(tolower($i)!=tolower(a[i])) ok=0; if (ok) print "#TMAegis# " $0; else print }' "$cfg"; } > "$t"
  if "$tma_sshd" -t -f "$t" >/dev/null 2>&1; then cat "$t" > "$cfg"; rm -f "$t"; tma_sshd_reload
  else rm -f "$t"; echo "sshd_config would be invalid after setting $kw; left unchanged" >&2; return 1; fi
}
# tma_other_admin MINUID: a non-root account with a login shell exists (do not lock the operator out)
tma_other_admin() { awk -F: -v m="$1" '$1!="root" && $3>=m && $7!~/(nologin|false)$/ {f=1} END{exit !f}' /etc/passwd; }
# tma_ssh_minver MAJOR MINOR: installed OpenSSH >= MAJOR.MINOR (needed for the "-algorithm" removal syntax)
tma_ssh_minver() {
  v=$(ssh -V 2>&1 | sed -n 's/^OpenSSH_\([0-9]*\)\.\([0-9]*\).*/\1 \2/p'); [ -n "$v" ] || return 1
  set -- $v "$1" "$2"; [ "$1" -gt "$3" ] || { [ "$1" -eq "$3" ] && [ "$2" -ge "$4" ]; }
}
tma_sshd_set Banner '/etc/issue.net'
[ -e '/etc/issue.net' ] || { echo 'Authorized uses only. All activity may be monitored and reported.' > '/etc/issue.net'; chmod 644 '/etc/issue.net'; }
